assign src_base = src_q;
assign dst_base = dst_q;
assign len      = len_q;

quote.exact:
// Writes overlap reads, so a failed write response can arrive in any busy state: abort.
if (wr_done && wr_err && state_q != IDLE && state_q != ERROR) begin
  rd_start   = 1'b0;
  wr_start   = 1'b0;
  err_code_d = 2'd3;
  state_d    = ERROR;
end

